;function initUniversalArchiveSearch(){
 const groups=[
  {key:"materials",label:"Materials",records:Ra,title:r=>r.name,sub:r=>`${r.id} · ${r.category}`},
  {key:"products",label:"Product Types",records:al,title:r=>r.style,sub:r=>`${r.id} · ${r.domain}${r.generalType?` · ${r.generalType}`:""}`},
  {key:"attributes",label:"Attributes",records:Fl,title:r=>r.value,sub:r=>`${r.id} · ${r.group}`},
  {key:"patterns",label:"Patterns",records:Bl,title:r=>r.name,sub:r=>`${r.id} · ${r.category}`}
 ];
 const navLabels={materials:"01Materials",products:"02Product Types",attributes:"03Attributes",patterns:"04Patterns"};
 let overlay=null,activeInput=null,lastQuery="";
 const norm=v=>String(v??"").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g,"");
 const recordText=r=>norm(JSON.stringify(r));
 function ensureOverlay(){
  if(overlay)return overlay;
  overlay=document.createElement("div");
  overlay.id="universal-search-results";
  Object.assign(overlay.style,{display:"none",position:"fixed",zIndex:"99999",background:"#fbfaf6",border:"1px solid #c6d2cc",boxShadow:"0 14px 36px rgba(20,45,44,.18)",maxHeight:"min(70vh,560px)",overflowY:"auto",padding:"8px",borderRadius:"2px",fontFamily:"Georgia,serif"});
  document.body.appendChild(overlay);
  return overlay;
 }
 function position(){
  if(!overlay||overlay.style.display==="none"||!activeInput)return;
  const r=activeInput.getBoundingClientRect();
  Object.assign(overlay.style,{left:`${Math.max(8,r.left)}px`,top:`${r.bottom+6}px`,width:`${Math.min(Math.max(r.width,300),520)}px`});
 }
 function hide(){if(overlay)overlay.style.display="none";lastQuery="";}
 function buttonFor(text){
  return [...document.querySelectorAll("button")].find(b=>b.textContent.replace(/\s+/g," ").trim().startsWith(text));
 }
 function navigate(group,id,title){
  hide();
  const nav=buttonFor(navLabels[group]);
  if(nav)nav.click();
  setTimeout(()=>{
   let target=group==="materials"?document.getElementById(`fabric-${id}`):null;
   if(!target){
    const wanted=[norm(id),norm(title)];
    target=[...document.querySelectorAll("article")].find(a=>wanted.some(v=>norm(a.textContent).includes(v)));
   }
   if(target){target.scrollIntoView({behavior:"smooth",block:"start"});target.style.outline="2px solid #0c5658";setTimeout(()=>target.style.outline="",1800);}
  },140);
 }
 function makeResult(group,record){
  const b=document.createElement("button");
  b.type="button";b.style.cssText="display:block;width:100%;text-align:left;border:0;border-top:1px solid #e0e5df;background:transparent;padding:9px 10px;cursor:pointer";
  b.onmouseenter=()=>b.style.background="#e9f1ed";b.onmouseleave=()=>b.style.background="transparent";
  const id=document.createElement("span");id.textContent=record.id;id.style.cssText="font:700 10px/1.2 ui-monospace,monospace;letter-spacing:.08em;color:#0c5658;display:block";
  const title=document.createElement("span");title.textContent=group.title(record);title.style.cssText="font:600 15px/1.25 Georgia,serif;color:#202a29;display:block;margin-top:3px";
  const sub=document.createElement("span");sub.textContent=group.sub(record);sub.style.cssText="font:10px/1.3 ui-monospace,monospace;color:#6d7772;display:block;margin-top:3px";
  b.append(id,title,sub);b.onclick=()=>navigate(group.key,record.id,group.title(record));return b;
 }
 function search(q){
  const o=ensureOverlay();lastQuery=q.trim();o.replaceChildren();
  if(!lastQuery){hide();return;}
  const needle=norm(lastQuery);let total=0;
  groups.forEach(group=>{
   const found=group.records.map(record=>{const text=recordText(record),title=norm(group.title(record));let score=text.indexOf(needle);if(score<0)return null;return {record,score:(title===needle?0:title.startsWith(needle)?1:2)+score/100000};}).filter(Boolean).sort((a,b)=>a.score-b.score).slice(0,6);
   if(!found.length)return;
   const head=document.createElement("div");head.textContent=`${group.label} · ${found.length}${found.length===6?"+":""}`;head.style.cssText="padding:7px 10px 5px;color:#0c5658;font:700 10px/1.2 ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase";o.appendChild(head);
   found.forEach(x=>{o.appendChild(makeResult(group,x.record));total++;});
  });
  if(!total){const empty=document.createElement("div");empty.textContent="No matches across the archive";empty.style.cssText="padding:16px 10px;color:#6d7772;font:12px Georgia,serif";o.appendChild(empty);}
  o.style.display="block";position();
 }
 function bind(){
  const inputs=[...document.querySelectorAll('input[type="search"]')].filter(i=>i.placeholder.includes("Search all sections")||i.placeholder.includes("Search fabrics"));
  inputs.forEach(input=>{if(input.dataset.universalSearchBound)return;input.dataset.universalSearchBound="1";input.addEventListener("focus",()=>{activeInput=input;search(input.value)});input.addEventListener("input",()=>{activeInput=input;search(input.value)});input.addEventListener("keydown",e=>{if(e.key==="Escape")hide();});});
 }
 bind();
 const observer=new MutationObserver(bind);observer.observe(document.body,{childList:true,subtree:true});
 window.addEventListener("resize",position,{passive:true});window.addEventListener("scroll",position,{passive:true});
 document.addEventListener("click",e=>{if(overlay&&overlay.style.display!=="none"&&!overlay.contains(e.target)&&e.target!==activeInput)hide();});
}
