(function(){
 if(window.__seasonalColorAnalysis)return; window.__seasonalColorAnalysis=true;
 const esc=v=>String(v??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
 const hexToRgb=h=>{const x=h.replace('#','');return [parseInt(x.slice(0,2),16),parseInt(x.slice(2,4),16),parseInt(x.slice(4,6),16)]};
 const rgbToHsl=(r,g,b)=>{r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b);let h=0,s=0,l=(max+min)/2;if(max!==min){const d=max-min;s=l>.5?d/(2-max-min):d/(max+min);switch(max){case r:h=(g-b)/d+(g<b?6:0);break;case g:h=(b-r)/d+2;break;default:h=(r-g)/d+4}h*=60}return [Math.round(h),Math.round(s*100),Math.round(l*100)]};
 const rangeFor=hex=>{try{const [h,s,l]=rgbToHsl(...hexToRgb(hex)),samples=[];for(const dh of [-8,0,8])for(const ds of [-12,0,12])for(const dl of [-10,0,10]){const hh=(h+dh+360)%360,ss=Math.max(0,Math.min(100,s+ds)),ll=Math.max(0,Math.min(100,l+dl));let c=(1-Math.abs(2*ll/100-1))*ss/100,x=c*(1-Math.abs((hh/60)%2-1)),mm=ll/100-c/2,r=0,g=0,b=0;hh<60?(r=c,g=x):hh<120?(r=x,g=c):hh<180?(g=c,b=x):hh<240?(g=x,b=c):hh<300?(r=x,b=c):(r=c,b=x);samples.push([Math.round((r+mm)*255),Math.round((g+mm)*255),Math.round((b+mm)*255)])}const mins=samples[0].map((_,i)=>Math.min(...samples.map(v=>v[i]))),maxs=samples[0].map((_,i)=>Math.max(...samples.map(v=>v[i]))),fmt=v=>v.map(n=>n.toString(16).padStart(2,'0')).join('').toUpperCase();return `Hue ${Math.max(0,h-8)}–${Math.min(360,h+8)}° · chroma ${Math.max(0,s-12)}–${Math.min(100,s+12)}% · lightness ${Math.max(0,l-10)}–${Math.min(100,l+10)}% · RGB ${mins.join(', ')}–${maxs.join(', ')} · HEX #${fmt(mins)}–#${fmt(maxs)}`}catch{return 'Use as a nearby color family, not an exact match'}};
 const paletteRows=key=>seasonalColorData[key]||[];
 const tabs=[['overview','All Seasons Overview'],['spring','Spring'],['summer','Summer'],['autumn','Autumn'],['winter','Winter'],['skinTones','Skin Tones'],['clashing','Clashing Colors']];
 let panel,content;
 function swatch(row,clashing=false){const hex=row['Hex Code'];const name=row['Color Name']||row['Named Shade']||'';const range=hex?rangeFor(hex):'Color family guidance';return `<article class="season-color-card" style="border:1px solid #d9dfd8;background:#fffdf8;padding:10px;display:flex;gap:10px;align-items:flex-start"><span aria-hidden="true" style="display:block;width:44px;height:44px;flex:none;background:${esc(hex||'#e7e2d9')};border:1px solid rgba(32,42,41,.2)"></span><div><strong style="display:block;font:600 14px/1.2 Georgia,serif;color:#202a29">${esc(name)}</strong><span style="display:block;margin-top:3px;font:10px/1.3 ui-monospace,monospace;color:#0c5658">${esc(row['Sub-Season']||row['Category']||'')} ${hex?`· ${esc(hex)}`:''}</span><span style="display:block;margin-top:5px;font:10px/1.35 ui-monospace,monospace;color:#69746e">${clashing?'Avoidance family · '+esc(range):'Practical range · '+esc(range)}</span></div></article>`}
 function overview(){return `<div><p style="font:13px/1.55 Georgia,serif;color:#4d5a54;max-width:760px">Use the season as a directional palette rather than a pass/fail color test. The hex values below are center references; garments, lighting, dye lots, texture, and personal contrast can move within the stated practical range. RGB and HEX ranges are approximate channel envelopes generated from the stated hue, chroma, and lightness ranges—not exact boundaries for physical dyes, fabrics, lighting, or garments.</p><div style="overflow:auto;margin-top:16px"><table style="width:100%;border-collapse:collapse;font:11px/1.4 Georgia,serif"><thead><tr style="text-align:left;border-bottom:2px solid #0c5658"><th style="padding:9px 8px">Season</th><th style="padding:9px 8px">Dominant quality</th><th style="padding:9px 8px">Undertone</th><th style="padding:9px 8px">Chroma</th><th style="padding:9px 8px">Contrast</th><th style="padding:9px 8px">Best metals</th><th style="padding:9px 8px">Anchor colors</th><th style="padding:9px 8px">Neutrals</th><th style="padding:9px 8px">Accents</th><th style="padding:9px 8px">Use cautiously</th></tr></thead><tbody>${seasonalColorData.overview.map(r=>`<tr style="border-bottom:1px solid #e2e6df;vertical-align:top"><td style="padding:9px 8px;font-weight:700;color:#0c5658;white-space:nowrap">${esc(r['Color Season'])}</td><td style="padding:9px 8px">${esc(r['Dominant Quality'])}</td><td style="padding:9px 8px">${esc(r['Skin Undertone'])}</td><td style="padding:9px 8px">${esc(r['Chroma (Saturation)'])}</td><td style="padding:9px 8px">${esc(r['Contrast Level'])}</td><td style="padding:9px 8px">${esc(r['Best Metals'])}</td><td style="padding:9px 8px">${esc(r['Best Anchor Colors'])}</td><td style="padding:9px 8px">${esc(r['Best Neutrals'])}</td><td style="padding:9px 8px">${esc(r['Best Accents'])}</td><td style="padding:9px 8px">${esc(r['Clashing Colors'])}</td></tr>`).join('')}</tbody></table></div></div>`}
 function palette(key,title){const rows=paletteRows(key);const subs=[...new Set(rows.map(r=>r['Sub-Season']).filter(Boolean))];return `<div><p style="font:13px/1.55 Georgia,serif;color:#4d5a54">${title} colors are presented as flexible families. Treat each swatch as a visual center, then move lighter, darker, softer, or clearer within the practical range shown on each card. RGB and HEX values are approximate channel envelopes, not exact physical-color boundaries.</p>${subs.map(sub=>`<section style="margin-top:18px"><h3 style="font:600 18px Georgia,serif;color:#202a29;margin:0 0 9px">${esc(sub)}</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px">${rows.filter(r=>r['Sub-Season']===sub).map(r=>swatch(r)).join('')}</div></section>`).join('')}</div>`}
 function skin(){const rows=seasonalColorData.skinTones;return `<div><p style="font:13px/1.55 Georgia,serif;color:#4d5a54">Skin-tone swatches are broad reference averages, not diagnostic labels. Use undertone and depth as flexible observations, with lighting and surrounding colors in mind.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;margin-top:16px">${rows.map(r=>`<article style="border:1px solid #d9dfd8;background:#fffdf8;padding:10px;display:flex;gap:10px"><span style="width:44px;height:44px;flex:none;background:${esc(r['Hex Code']||'#eee')};border:1px solid rgba(32,42,41,.2)"></span><div><strong style="display:block;font:600 14px Georgia,serif">${esc(r['Named Shade'])}</strong><span style="display:block;font:10px ui-monospace,monospace;color:#0c5658">${esc(r['Category'])} · ${esc(r['Depth Range'])}</span><span style="display:block;margin-top:5px;font:10px ui-monospace,monospace;color:#69746e">Practical range · nearby undertone/depth family</span></div></article>`).join('')}</div></div>`}
 function clash(){const rows=seasonalColorData.clashing;const subs=[...new Set(rows.map(r=>r['Sub-Season']).filter(Boolean))];return `<div><p style="font:13px/1.55 Georgia,serif;color:#4d5a54">Clashing colors are guidance, not prohibitions. The entries describe families that may compete with a palette near the face; distance, texture, scale, and styling can make them workable.</p>${subs.map(sub=>`<section style="margin-top:18px"><h3 style="font:600 18px Georgia,serif;color:#202a29;margin:0 0 9px">${esc(sub)}</h3><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px">${rows.filter(r=>r['Sub-Season']===sub).map(r=>swatch(r,true)).join('')}</div></section>`).join('')}</div>`}
 function render(key){if(!content)return;content.innerHTML=key==='overview'?overview():key==='skinTones'?skin():key==='clashing'?clash():palette(key,key.charAt(0).toUpperCase()+key.slice(1));panel.querySelectorAll('[data-color-tab]').forEach(b=>b.onclick=()=>render(b.dataset.colorTab));}
 function open(){if(panel){panel.style.display='block';return}panel=document.createElement('div');panel.id='seasonal-color-analysis';panel.style.cssText='position:fixed;inset:0;z-index:100000;overflow:auto;background:#f5f3ec;padding:20px';panel.innerHTML=`<div style="max-width:1500px;margin:0 auto;background:#fbfaf6;border:1px solid #cbd5ce;min-height:calc(100vh - 40px);box-shadow:0 20px 60px rgba(20,45,44,.16)"><header style="position:sticky;top:0;z-index:2;background:#fbfaf6;border-bottom:1px solid #cbd5ce;padding:18px 20px;display:flex;justify-content:space-between;gap:16px;align-items:flex-start"><div><p style="margin:0 0 5px;font:700 10px ui-monospace,monospace;letter-spacing:.14em;text-transform:uppercase;color:#0c5658">Color analysis · tone & fit</p><h1 style="margin:0;font:600 28px Georgia,serif;color:#202a29">Seasonal Color Analysis</h1><p style="margin:7px 0 0;font:12px/1.45 Georgia,serif;color:#69746e">A practical palette guide with flexible color families rather than rigid exact matches.</p></div><button id="close-seasonal-color-analysis" type="button" style="border:1px solid #b8c6be;background:#fffdf8;color:#0c5658;padding:8px 11px;cursor:pointer;font:700 10px ui-monospace,monospace;letter-spacing:.08em">CLOSE ×</button></header><nav style="display:flex;gap:6px;flex-wrap:wrap;padding:14px 20px;border-bottom:1px solid #dfe5de;background:#f7f6f0">${tabs.map(([k,t])=>`<button data-color-tab="${k}" type="button" style="border:1px solid #b8c6be;background:#e8f1ed;color:#0c5658;padding:8px 10px;cursor:pointer;font:700 10px ui-monospace,monospace;letter-spacing:.05em">${esc(t)}</button>`).join('')}</nav><main id="seasonal-color-content" style="padding:22px 20px"></main></div>`;document.body.appendChild(panel);content=panel.querySelector('#seasonal-color-content');panel.querySelector('#close-seasonal-color-analysis').onclick=()=>panel.style.display='none';panel.addEventListener('click',e=>{if(e.target===panel)panel.style.display='none'});render('overview')}
 function bind(){const input=document.querySelector('input[placeholder*="Search all sections"]')||document.querySelector('input[placeholder*="Search fabrics"]');if(!input)return;const wrap=input.closest('div.relative')||input.parentElement;const parent=wrap.parentElement||wrap;if(parent.querySelector('[data-color-analysis-trigger]'))return;const b=document.createElement('button');b.type='button';b.dataset.colorAnalysisTrigger='1';b.textContent='Color Analysis';b.style.cssText='margin-right:8px;border:1px solid #b8c6be;background:#e8f1ed;color:#0c5658;padding:8px 10px;cursor:pointer;font:700 10px ui-monospace,monospace;letter-spacing:.05em;white-space:nowrap';b.onclick=open;parent.insertBefore(b,wrap)}
 bind();new MutationObserver(bind).observe(document.body,{childList:true,subtree:true});
})();